(function(){var o={once:true,offset:60},observer;function init(options){o=Object.assign(o,options||{});if(!('IntersectionObserver'in window)){document.querySelectorAll('[data-aos]').forEach(function(e){e.classList.add('aos-animate')});return}observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('aos-animate');if(o.once)observer.unobserve(entry.target)}})},{rootMargin:'0px 0px -'+o.offset+'px 0px',threshold:.05});document.querySelectorAll('[data-aos]').forEach(function(e){observer.observe(e)})}window.AOS={init:init,refreshHard:function(){if(observer)observer.disconnect();init(o)}}})();
